        model.addConstr(sum_xk >= y[k], f'setup_cost_{k}_lower')
        model.addConstr(y[k] <= sum_xk, f'setup_cost_{k}_upper')

    # Optimize the model
    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f'FINAL_OBJECTIVE={model.objVal}')

